<template>
  <main class="kvm-page managed-clusters-page">
    <header class="page-head"><div><span class="eyebrow">{{ t('eyebrow') }}</span><h1>{{ t('title') }}</h1><p>{{ t('subtitle') }}</p></div><button class="btn role-secondary" @click="goBack">{{ t('back') }}</button></header>
    <div class="notice"><strong>{{ t('scopeTitle') }}</strong><p>{{ t('scopeHelp') }}</p></div>
    <div v-if="error" class="banner error" role="alert">{{ error }}</div>
    <section v-if="canManage" class="group-form">
      <h2>{{ t('createTitle') }}</h2><p>{{ t('createHelp') }}</p>
      <form @submit.prevent="createGroup"><label>{{ t('name') }}<input v-model.trim="name" maxlength="80" required></label><div class="host-grid"><label v-for="host in readyHosts" :key="host.id" class="host-option"><input v-model="selectedHostIds" type="checkbox" :value="host.id"><span><strong>{{ host.hostname || host.name }}</strong><small>{{ host.address }} · {{ t('ready') }}</small></span></label></div><div class="actions"><button class="btn role-primary" :disabled="saving || selectedHostIds.length < 2">{{ saving ? t('creating') : t('create') }}</button></div></form>
    </section>
    <section v-else class="notice"><strong>{{ t('readOnly') }}</strong><p>{{ t('readOnlyHelp') }}</p></section>
    <section class="group-list"><div class="section-head"><h2>{{ t('groupsTitle') }}</h2><button class="btn role-secondary btn-sm" :disabled="loading" @click="load">{{ t('refresh') }}</button></div><p v-if="!groups.length" class="empty">{{ t('empty') }}</p><article v-for="group in groups" :key="group.id" class="group-row"><div><strong>{{ group.name }}</strong><small>{{ memberNames(group) }}</small><span class="state warning-state"><i></i>{{ t('setupState') }}</span></div><div class="actions"><button class="btn role-secondary btn-sm" @click="openGroup(group)">{{ t('open') }}</button><button v-if="canManage" class="btn role-link btn-sm danger-text" @click="removeGroup(group)">{{ t('removeGroup') }}</button></div></article></section>
    <section v-if="selectedGroup" class="inventory"><div class="section-head"><div><h2>{{ selectedGroup.name }}</h2><small>{{ inventory?.checked_at ? `${t('checked')}: ${new Date(inventory.checked_at).toLocaleString()}` : '' }}</small></div><button class="btn role-secondary btn-sm" :disabled="inventoryLoading" @click="loadInventory">{{ inventoryLoading ? t('loading') : t('refresh') }}</button></div>
      <div class="notice compact"><strong>{{ t('capabilityTitle') }}</strong><p>{{ t('capabilityHelp') }}</p></div>
      <div v-if="inventoryError" class="banner error" role="alert">{{ inventoryError }}</div>
      <div v-if="inventory" class="table-wrap"><table class="table"><thead><tr><th>{{ t('host') }}</th><th>{{ t('hostState') }}</th><th>{{ t('vms') }}</th><th>{{ t('storage') }}</th><th>{{ t('networks') }}</th></tr></thead><tbody><tr v-for="host in inventory.hosts" :key="host.host_id"><td><strong>{{ host.host_name }}</strong></td><td>{{ host.status }}</td><td>{{ host.vms?.length || 0 }}<small v-for="vm in host.vms" :key="vm.name">{{ vm.name }} · {{ vm.state || vm.status }}</small></td><td><small v-for="pool in host.storage_pools || []" :key="pool.name">{{ pool.name }}</small><span v-if="!host.storage_pools?.length">—</span></td><td><small v-for="network in host.libvirt_networks || []" :key="network.name">{{ network.name }}</small><span v-if="!host.libvirt_networks?.length">—</span></td></tr></tbody></table></div>
      <h3>{{ t('crossHostVms') }}</h3><div v-if="inventory?.vms?.length" class="vm-cards"><article v-for="vm in inventory.vms" :key="`${vm.host_id}-${vm.name}`"><strong>{{ vm.name }}</strong><small>{{ vm.host_name }}</small><span>{{ vm.state || vm.status }}</span></article></div><p v-else class="empty">{{ t('noVms') }}</p>
    </section>
  </main>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
const apiBase = (process.env.VUE_APP_KVM_API || '/kvm-api').replace(/\/$/, '');
export default defineComponent({
  name: 'ManagedKvmClusters',
  data() { return { name: '', hosts: [] as any[], groups: [] as any[], selectedHostIds: [] as string[], selectedGroup: null as any, inventory: null as any, loading: false, saving: false, inventoryLoading: false, error: '', inventoryError: '', canManage: false }; },
  computed: { readyHosts(): any[] { return this.hosts.filter((host) => host.status === 'ready'); } },
  mounted() { this.load(); },
  methods: {
    t(key: string) { const translate = (this as any).$store?.getters?.['i18n/t']; return translate ? translate(`kvmManager.managedClusters.${key}`) : key; },
    async request(path: string, options: RequestInit = {}) { const response = await fetch(`${apiBase}${path}`, { credentials: 'include', cache: 'no-store', ...options, headers: { ...(options.body ? { 'Content-Type': 'application/json' } : {}), ...(options.headers || {}) } }); const body = response.status === 204 ? null : await response.json().catch(() => ({})); if (!response.ok) throw new Error(body?.detail || `Request failed (${response.status})`); return body; },
    async load() { this.loading = true; this.error = ''; try { [this.groups, this.hosts] = await Promise.all([this.request('/managed-clusters'), this.request('/hosts')]); const permissions = await this.request('/permissions'); this.canManage = Boolean(permissions?.canManageClusters); } catch (error) { this.error = (error as Error).message; } finally { this.loading = false; } },
    async createGroup() { if (this.selectedHostIds.length < 2) return; this.saving = true; this.error = ''; try { const created = await this.request('/managed-clusters', { method: 'POST', body: JSON.stringify({ name: this.name, host_ids: this.selectedHostIds }) }); this.name = ''; this.selectedHostIds = []; await this.load(); this.openGroup(created); } catch (error) { this.error = (error as Error).message; } finally { this.saving = false; } },
    async openGroup(group: any) { this.selectedGroup = group; await this.loadInventory(); },
    async loadInventory() { if (!this.selectedGroup) return; this.inventoryLoading = true; this.inventoryError = ''; try { this.inventory = await this.request(`/managed-clusters/${this.selectedGroup.id}/inventory`); } catch (error) { this.inventoryError = (error as Error).message; } finally { this.inventoryLoading = false; } },
    async removeGroup(group: any) { try { await this.request(`/managed-clusters/${group.id}`, { method: 'DELETE' }); if (this.selectedGroup?.id === group.id) { this.selectedGroup = null; this.inventory = null; } await this.load(); } catch (error) { this.error = (error as Error).message; } },
    memberNames(group: any) { return (group.members || []).map((host: any) => host.hostname || host.name).join(', '); },
    goBack() { (this as any).$router?.push({ name: 'kvm-c-clusters', params: { cluster: '_' } }); },
  },
});
</script>

<style scoped>
.managed-clusters-page{max-width:1160px;margin:0 auto;padding:24px;box-sizing:border-box}.page-head,.section-head,.group-row{display:flex;justify-content:space-between;align-items:flex-start;gap:16px}.page-head{margin-bottom:18px}.page-head h1{margin:4px 0;font-weight:500}.page-head p,.group-form>p,.section-head small{color:var(--muted,#929baa)}.eyebrow{font-size:10px;letter-spacing:.08em;color:var(--muted,#929baa)}.notice{margin:14px 0;padding:13px 15px;border-left:3px solid var(--primary,#4b91e2);background:color-mix(in srgb,var(--primary,#4b91e2) 9%,var(--body-bg,#252b33));border-radius:4px}.notice p{margin:4px 0 0;color:var(--muted,#a4adba);font-size:13px;line-height:1.45}.compact{margin:10px 0}.group-form,.group-list,.inventory{margin:18px 0;padding:18px;border:1px solid var(--border,#394452);border-radius:7px;background:var(--body-bg,#252b33)}.group-form h2,.group-list h2,.inventory h2{margin:0;font-size:18px}.group-form form>label{display:grid;gap:6px;max-width:480px;font-size:13px;font-weight:600}.group-form input:not([type=checkbox]){height:38px;padding:8px;border:1px solid var(--border,#4b5563);border-radius:4px;background:var(--body-bg,#252b33);color:var(--body-text,#e5e7eb)}.host-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:8px;margin:16px 0}.host-option{display:flex;align-items:center;gap:10px;padding:11px;border:1px solid var(--border,#394452);border-radius:5px;cursor:pointer}.host-option span,.group-row small,.vm-cards small{display:block}.host-option small,.group-row small{margin-top:4px;color:var(--muted,#929baa);font-size:12px}.actions{display:flex;gap:8px;align-items:center}.group-row{align-items:center;padding:13px 0;border-top:1px solid var(--border,#394452)}.group-row>div:first-child{display:grid;gap:4px}.state{display:inline-flex;align-items:center;gap:5px;color:#dda84d;font-size:12px}.state i{width:7px;height:7px;border-radius:50%;background:currentColor}.empty{padding:16px;text-align:center;color:var(--muted,#929baa)}.table-wrap{overflow:auto}.table{width:100%;border-collapse:collapse}.table th,.table td{padding:10px;text-align:left;border-bottom:1px solid var(--border,#394452);vertical-align:top}.table td small{display:block;margin-top:4px;color:var(--muted,#929baa)}.inventory h3{margin:22px 0 10px;font-size:16px}.vm-cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:10px}.vm-cards article{display:grid;gap:5px;padding:12px;border:1px solid var(--border,#394452);border-radius:5px}.vm-cards small{color:var(--muted,#929baa)}.danger-text{color:#df747b}@media(max-width:700px){.managed-clusters-page{padding:16px 12px}.page-head,.group-row{flex-direction:column;align-items:stretch}.group-form,.group-list,.inventory{padding:14px}}
</style>
